import type { Booking, Prisma, PrismaClient } from '@prisma/client';
import { prisma } from '../../db/client.js';
import { BOOKING_ACTIVE } from './schema.js';

export interface BookingData {
  roomId: string;
  userId: string;
  title: string;
  startsAt: Date;
  endsAt: Date;
}

export interface BookingFilter {
  roomId?: string;
  userId?: string;
  status?: string;
  from?: Date;
  to?: Date;
  limit: number;
  offset: number;
}

export type CreateResult = { conflict: Booking } | { booking: Booking };
export type UpdateResult = { conflict: Booking } | { booking: Booking };

type PrismaTx = Prisma.TransactionClient | PrismaClient;

function findConflict(
  tx: PrismaTx,
  roomId: string,
  startsAt: Date,
  endsAt: Date,
  excludeId?: string,
): Promise<Booking | null> {
  return tx.booking.findFirst({
    where: {
      roomId,
      status: BOOKING_ACTIVE,
      startsAt: { lt: endsAt },
      endsAt: { gt: startsAt },
      ...(excludeId ? { id: { not: excludeId } } : {}),
    },
  });
}

export async function createChecked(data: BookingData): Promise<CreateResult> {
  return prisma.$transaction(async (tx) => {
    const conflict = await findConflict(tx, data.roomId, data.startsAt, data.endsAt);
    if (conflict) return { conflict };
    const booking = await tx.booking.create({ data });
    return { booking };
  });
}

export function findById(id: string): Promise<Booking | null> {
  return prisma.booking.findUnique({ where: { id } });
}

